boolean dfs(char[][] b, String word, int r, int c, int i) {
    if (i == word.length()) return true;                       // every letter matched
    if (r < 0 || r >= b.length || c < 0 || c >= b[0].length || b[r][c] != word.charAt(i)) return false;
    char saved = b[r][c];
    b[r][c] = '#';                                             // mark: on the current path
    boolean found = dfs(b, word, r + 1, c, i + 1) || dfs(b, word, r - 1, c, i + 1)
                 || dfs(b, word, r, c + 1, i + 1) || dfs(b, word, r, c - 1, i + 1);
    b[r][c] = saved;                                           // un-mark when backing out
    return found;
}

