from collections import Counter

def exist(board, word):
    m, n = len(board), len(board[0])
    count = Counter(ch for row in board for ch in row)
    if any(count[ch] < k for ch, k in Counter(word).items()):
        return False                      # not enough letters
    if count[word[0]] > count[word[-1]]:
        word = word[::-1]                 # start from the rarer end

    def dfs(r, c, i):
        if i == len(word):
            return True
        if r < 0 or r >= m or c < 0 or c >= n or board[r][c] != word[i]:
            return False
        saved = board[r][c]
        board[r][c] = "#"
        found = dfs(r + 1, c, i + 1) or dfs(r - 1, c, i + 1) or dfs(r, c + 1, i + 1) or dfs(r, c - 1, i + 1)
        board[r][c] = saved
        return found

    return any(dfs(r, c, 0) for r in range(m) for c in range(n))

boolean exist(char[][] board, String word) {
    int[] count = new int[128], need = new int[128];
    for (char[] row : board) for (char ch : row) count[ch]++;
    for (char ch : word.toCharArray()) need[ch]++;
    for (int ch = 0; ch < 128; ch++) if (count[ch] < need[ch]) return false;   // not enough letters
    if (count[word.charAt(0)] > count[word.charAt(word.length() - 1)]) {
        word = new StringBuilder(word).reverse().toString();                   // start from the rarer end
    }
    for (int r = 0; r < board.length; r++) {
        for (int c = 0; c < board[0].length; c++) if (dfs(board, word, r, c, 0)) return true;
    }
    return false;
}

boolean dfs(char[][] b, String word, int r, int c, int i) {
    if (i == word.length()) return true;
    if (r < 0 || r >= b.length || c < 0 || c >= b[0].length || b[r][c] != word.charAt(i)) return false;
    char saved = b[r][c];
    b[r][c] = '#';
    boolean found = dfs(b, word, r + 1, c, i + 1) || dfs(b, word, r - 1, c, i + 1)
                 || dfs(b, word, r, c + 1, i + 1) || dfs(b, word, r, c - 1, i + 1);
    b[r][c] = saved;
    return found;
}

