bool exist(vector<vector<char>>& board, string word) {
    int count[128] = {}, need[128] = {};
    for (auto& row : board) for (char ch : row) count[(int)ch]++;
    for (char ch : word) need[(int)ch]++;
    for (int ch = 0; ch < 128; ch++) if (count[ch] < need[ch]) return false;   // not enough letters
    if (count[(int)word[0]] > count[(int)word.back()]) reverse(word.begin(), word.end());   // rarer end first
    for (int r = 0; r < (int)board.size(); r++)
        for (int c = 0; c < (int)board[0].size(); c++) if (dfs(board, word, r, c, 0)) return true;
    return false;
}
